// Shelly 3EM (shelly-wp/status/em:0 + emdata:0) -> Victron Virtual Device "Waermepumpe"
// nur Pfade, die AC-Load und Energiezaehler (alle Palette-Versionen) kennen
const c = String(msg.topic).split('/').pop(), p = msg.payload;
if (!p || typeof p !== 'object') return null;
const out = {};
const put = (k, v) => { if (typeof v === 'number' && isFinite(v)) out[k] = Math.round(v * 1000) / 1000; };

if (c === 'em:0') {                                   // Momentanwerte
    put('Ac/Power', p.total_act_power);
    for (const [L, x] of [['L1', 'a'], ['L2', 'b'], ['L3', 'c']]) {
        put(`Ac/${L}/Power`, p[x + '_act_power']);
        put(`Ac/${L}/Voltage`, p[x + '_voltage']);
        put(`Ac/${L}/Current`, p[x + '_current']);
        put(`Ac/${L}/PowerFactor`, p[x + '_pf']);
    }
    node.status({ fill: 'green', shape: 'dot', text: Math.round(p.total_act_power) + ' W' });
} else if (c === 'emdata:0') {                        // Zaehlerstaende Wh -> kWh
    put('Ac/Energy/Forward', p.total_act / 1000);
    put('Ac/L1/Energy/Forward', p.a_total_act_energy / 1000);
    put('Ac/L2/Energy/Forward', p.b_total_act_energy / 1000);
    put('Ac/L3/Energy/Forward', p.c_total_act_energy / 1000);
} else {
    return null;
}
if (!Object.keys(out).length) return null;
msg.payload = out;
return msg;
